// Synchronous model: no real DOM, timers, or Worker.
// One old worker controls one open tab; a new worker is deployed.
const openTabsControlledByOld = 1;
const USE_SKIP_WAITING = true;
const trace = [];

function deploy(useSkipWaiting, oldTabs) {
  trace.push('register');
  trace.push('install:precache-app-shell');
  // A freshly installed worker enters waiting.
  let state = 'waiting';
  if (useSkipWaiting) {
    trace.push('skipWaiting');
    state = 'activatable';
  } else if (oldTabs > 0) {
    // Stuck: cannot advance while old worker still controls a tab.
    trace.push('blocked:old-tabs=' + oldTabs);
    return state; // remains 'waiting'
  } else {
    state = 'activatable';
  }
  trace.push('activate:clean-old-caches');
  trace.push('clients.claim');
  trace.push('controlling-fetch');
  return 'activated';
}

const finalState = deploy(USE_SKIP_WAITING, openTabsControlledByOld);
console.log(trace.join(' -> ') + ' | final=' + finalState);
